// Thin wrapper over the wasm-pack output in ./pkg (generated by `just build-wasm`,
// not committed). Initialization is memoized so every caller shares one module
// instance; the same wrapper will be used from the compositor Worker.
import init, { hello_scene, version } from './pkg/prostor_wasm.js';
import type { Scene } from '#lib/generated/Scene';

let ready: Promise<void> | undefined;

/** Instantiates the wasm module once. Safe to call repeatedly. */
export function loadWasm(): Promise<void> {
	ready ??= init().then(() => undefined);
	return ready;
}

/** Sample scene produced by the Rust core (hello-world round trip). */
export async function helloScene(): Promise<Scene> {
	await loadWasm();
	return hello_scene() as Scene;
}

/** Version of the prostor-wasm crate. */
export async function wasmVersion(): Promise<string> {
	await loadWasm();
	return version();
}
